2	<html lang="en">
3	<head>
4	  <meta charset="utf-8">
5	  <meta name="viewport" content="width=device-width,initial-scale=1">
6	  <title>Keep — Bookmark prototype</title>
7	  <style>
8	    :root { color-scheme: light; --ink:#14251d; --muted:#68736e; --line:#dfe6e2; --brand:#176b4b; --brand2:#e5f4ec; --paper:#fbfcfa; }
9	    * { box-sizing:border-box; }
10	    body { margin:0; font:15px/1.5 Inter,ui-sans-serif,system-ui,-apple-system,sans-serif; color:var(--ink); background:#f2f5f2; }
11	    button,input { font:inherit; }
12	    .shell { max-width:1040px; min-height:100vh; margin:auto; background:var(--paper); border-inline:1px solid #e8ece9; }
13	    header { height:74px; display:flex; align-items:center; justify-content:space-between; padding:0 38px; border-bottom:1px solid var(--line); }
14	    .brand { display:flex; align-items:center; gap:11px; font-size:19px; font-weight:760; letter-spacing:-.02em; }
15	    .brand-mark { width:32px; height:32px; display:grid; place-items:center; color:white; background:var(--brand); border-radius:10px 10px 10px 3px; font-size:18px; }
16	    .count { color:var(--muted); font-size:13px; }
17	    main { max-width:780px; margin:0 auto; padding:70px 28px; }
18	    h1 { margin:0; font-size:34px; letter-spacing:-.04em; line-height:1.12; }
19	    .lead { margin:12px 0 30px; color:var(--muted); font-size:16px; }
20	    .capture { padding:8px; display:flex; gap:8px; background:white; border:1px solid var(--line); border-radius:15px; box-shadow:0 10px 30px rgba(31,61,46,.07); }
21	    .capture:focus-within { border-color:#86bca7; box-shadow:0 0 0 3px #dff2e9,0 10px 30px rgba(31,61,46,.07); }
22	    input { min-width:0; flex:1; border:0; outline:0; padding:11px 12px; color:var(--ink); background:transparent; }
23	    input::placeholder { color:#919b96; }
24	    button { border:0; border-radius:10px; padding:11px 18px; cursor:pointer; font-weight:680; }
25	    .primary { color:white; background:var(--brand); }
26	    .primary:hover { background:#115a3e; }
27	    .primary:disabled { opacity:.55; cursor:default; }
28	    .hint { margin:9px 4px 0; min-height:20px; font-size:13px; color:var(--muted); }
29	    .section-head { margin-top:54px; display:flex; align-items:end; justify-content:space-between; }
30	    h2 { margin:0; font-size:18px; letter-spacing:-.015em; }
31	    .empty { margin-top:16px; padding:54px 20px; text-align:center; border:1px dashed #cfd8d3; border-radius:18px; color:var(--muted); background:#f8faf8; }
32	    .empty-icon { margin:auto auto 12px; width:44px; height:44px; display:grid; place-items:center; border-radius:14px; color:var(--brand); background:var(--brand2); font-size:21px; }
33	    .card { display:none; margin-top:16px; padding:18px; grid-template-columns:92px 1fr; gap:18px; border:1px solid var(--line); border-radius:18px; background:white; box-shadow:0 7px 20px rgba(31,61,46,.05); }
34	    .thumb { min-height:92px; border-radius:12px; background:linear-gradient(145deg,#d9eadf,#82b49d); display:grid; place-items:center; color:white; font-size:34px; }
35	    .domain { display:flex; align-items:center; gap:7px; color:var(--muted); font-size:12px; }
36	    .favicon { width:17px; height:17px; border-radius:5px; display:grid; place-items:center; color:white; background:#202a25; font-size:10px; font-weight:800; }
37	    .title { margin:7px 0 5px; font-size:17px; font-weight:750; }
38	    .desc { margin:0; color:var(--muted); font-size:14px; }
39	    dialog { width:min(570px,calc(100% - 32px)); border:0; border-radius:20px; padding:0; color:var(--ink); box-shadow:0 24px 80px rgba(18,40,29,.28); }
40	    dialog::backdrop { background:rgba(17,35,26,.42); backdrop-filter:blur(2px); }
41	    .modal { padding:26px; }
42	    .modal h2 { font-size:22px; }
43	    .modal .sub { margin:6px 0 20px; color:var(--muted); }
44	    .preview { display:grid; grid-template-columns:112px 1fr; gap:16px; padding:14px; border:1px solid var(--line); border-radius:15px; background:#f8faf8; }
45	    .preview .thumb { min-height:108px; }
46	    .preview-url { margin-top:8px; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; color:var(--muted); font-size:12px; }
47	    .actions { display:flex; justify-content:flex-end; gap:9px; margin-top:22px; }
48	    .secondary { color:var(--ink); background:#edf1ee; }
49	    .toast { position:fixed; left:50%; bottom:28px; transform:translate(-50%,20px); padding:11px 17px; color:white; background:#18372a; border-radius:10px; opacity:0; transition:.22s; pointer-events:none; }
50	    .toast.show { opacity:1; transform:translate(-50%,0); }
51	    @media (max-width:600px) { header{padding:0 20px} main{padding:45px 18px}.card,.preview{grid-template-columns:1fr}.capture{align-items:stretch}.capture button{padding-inline:12px} }
52	  </style>
53	</head>
54	<body>
55	  <div class="shell" data-harness-ready="true">
56	    <header><div class="brand"><span class="brand-mark">↗</span> Keep</div><div class="count" id="count">0 bookmarks</div></header>
57	    <main>
58	      <h1>A home for the links<br>you want to remember.</h1>
59	      <p class="lead">Paste a web address and Keep will fill in the useful details.</p>
60	      <form class="capture" id="capture">
61	        <input id="url" type="url" required autocomplete="off" placeholder="Paste a web address…" aria-label="Web address">
62	        <button class="primary" id="add" type="submit">Add link</button>
63	      </form>
64	      <div class="hint" id="hint">Try: https://fortelabs.com/blog/basboverview/</div>
65	      <div class="section-head"><h2>All bookmarks</h2></div>
66	      <div class="empty" id="empty"><div class="empty-icon">⌁</div><strong>Nothing saved yet</strong><br>Your first useful link will appear here.</div>
67	      <article class="card" id="card">
68	        <div class="thumb">✦</div>
69	        <div><div class="domain"><span class="favicon">F</span> fortelabs.com</div><div class="title">The PARA Method: The Simple System for Organizing Your Digital Life</div><p class="desc">A simple, comprehensive system for organizing any type of digital information across any platform.</p></div>
70	      </article>
71	    </main>
72	  </div>
73	  <dialog id="previewDialog">
74	    <div class="modal">
75	      <h2>Here’s what we found</h2>
76	      <p class="sub">Check the details before adding this link.</p>
77	      <div class="preview">
78	        <div class="thumb">✦</div>
79	        <div><div class="domain"><span class="favicon">F</span> fortelabs.com</div><div class="title">The PARA Method: The Simple System for Organizing Your Digital Life</div><p class="desc">A simple, comprehensive system for organizing any type of digital information across any platform.</p><div class="preview-url" id="previewUrl"></div></div>
80	      </div>
81	      <div class="actions"><button class="secondary" id="cancel">Cancel</button><button class="primary" id="save">Save bookmark</button></div>
82	    </div>
83	  </dialog>
84	  <div class="toast" id="toast">Bookmark saved</div>
85	  <script>
86	    const form=document.querySelector('#capture'), input=document.querySelector('#url'), dialog=document.querySelector('#previewDialog');
87	    form.addEventListener('submit',e=>{e.preventDefault();document.querySelector('#previewUrl').textContent=input.value;dialog.showModal()});
88	    document.querySelector('#cancel').onclick=()=>dialog.close();
89	    document.querySelector('#save').onclick=()=>{dialog.close();document.querySelector('#empty').style.display='none';document.querySelector('#card').style.display='grid';document.querySelector('#count').textContent='1 bookmark';input.value='';document.querySelector('#hint').textContent='';const t=document.querySelector('#toast');t.classList.add('show');setTimeout(()=>t.classList.remove('show'),1800)};
90	  </script>
91	</body>
92	</html>
