over-edit{position:absolute;right:14px;top:14px;width:38px;height:38px;padding:0;display:none;color:var(--brand);background:var(--pale);font-size:18px}.card:hover .hover-edit,.hover-edit:focus{display:block}dialog{width:min(560px,calc(100% - 32px));border:0;border-radius:20px;padding:0;color:var(--ink);box-shadow:0 24px 80px rgba(18,40,29,.28)}dialog::backdrop{background:rgba(17,35,26,.42);backdrop-filter:blur(2px)}.modal{padding:26px}.modal h2{margin:0;font-size:22px}.sub{margin:6px 0 20px;color:var(--muted)}label{display:block;margin:13px 0 5px;font-size:12px;font-weight:740;color:var(--muted)}input,textarea{width:100%;padding:10px;border:1px solid #cad6cf;border-radius:9px;outline:0}input:focus,textarea:focus{border-color:#68a78e;box-shadow:0 0 0 3px #dff2e9}textarea{min-height:90px;resize:vertical}.actions{display:flex;justify-content:flex-end;gap:9px;margin-top:20px}.secondary{background:#edf1ee}.primary{color:white;background:var(--brand)}.toast{position:fixed;left:50%;bottom:28px;transform:translate(-50%,20px);padding:11px 17px;color:#fff;background:#18372a;border-radius:10px;opacity:0;transition:.2s}.toast.show{opacity:1;transform:translate(-50%,0)}@media(max-width:600px){.card{grid-template-columns:1fr}.thumb{min-height:130px}}
