18	    if(version==='a'){control.innerHTML='<button class="edit" id="trigger">Edit</button>'}
19	    if(version==='b'){control.innerHTML='<button class="more" id="trigger" aria-label="More actions">•••</button>';document.querySelector('#trigger').onclick=()=>menu.style.display=menu.style.display==='block'?'none':'block';document.querySelector('#menuEdit').onclick=openEdit}
