21	    if(version!=='b')document.querySelector('#trigger').onclick=openEdit;
22	    document.querySelector('#cancel').onclick=()=>dialog.close();
23	    document.querySelector('#save').onclick=()=>{document.querySelector('.title').textContent=document.querySelector('#title').value;document.querySelector('.desc').textContent=document.querySelector('#desc').value;dialog.close();const t=document.querySelector('#toast');t.classList.add('show');setTimeout(()=>t.classList.remove('show'),1600)};
